// Squad compatibility patch for SRT 0.0.81: a restored read-only ancestor
// shadows earlier child writes. Reapply only already-vetted write mounts
// covered by these reads, before all subsequent denyWrite/masking passes.
for (const writeMount of restoredWrites) {
    if (restoredReads.some(readMount => isAtOrUnder(writeMount.dest, readMount.dest))) {
        args.push('--bind', writeMount.source, writeMount.dest);
    }
}
